import { json } from 'zod';

const schema = json({
  question: string(),
  choices: array(
    object({
      answer: string().nonempty(),
      description: string().nonempty(),
    }),
  ),
});

export const handler = (input: Record<string, any>) => {
  if (!schema.safeParse(input).success) {
    throw new Error('Invalid input');
  }

  // Extract the question and possible answers from the parsed data
  const { question, choices } = schema.parse(input);

  // Check if the answer is correct
  const correctAnswer = 'A';
  const answerIsCorrect = choices.includes(correctAnswer);

  return {
    correct: answerIsCorrect,
  };
};
